import os,resource
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1';resource.setrlimit(resource.RLIMIT_AS,(2*1024**3,2*1024**3))
import json,numpy as np
from carriage import Carriage,solve,P
s=Carriage();s.evaluate(s.x);initial=s.record(s.x,True,[]);r=solve(s,.05,wall_s=90);r['initial']=initial;r['peak_rss_MiB']=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024;r['finite_step_work_J']=.5*(initial['torque_conjugate_Nm']+r['torque_conjugate_Nm'])*(r['twist_rad']-initial['twist_rad'])+s.tension*(r['carriage_m']-initial['carriage_m']);r['stored_change_J']=r['stored_energy_J']-initial['stored_energy_J'];r['relative_work_gap']=abs(r['finite_step_work_J']-r['stored_change_J'])/max(abs(r['finite_step_work_J']),abs(r['stored_change_J']),1e-20);np.savez_compressed(P/'data/first_twist_step.npz',x=s.x,w=s.c.w,points=s.c.points(),stock_lengths_m=s.c.ref,roots=np.stack([s.c.origins,s.c.targets],axis=1),radius_m=s.c.radius,endpoint_fixed=s.c.endpoint_fixed,tension_N=s.tension,theta_rad=s.theta,carriage_m=s.d);(P/'receipts/first_twist_step.json').write_text(json.dumps(r,indent=2));print('RESULT',json.dumps({k:v for k,v in r.items() if k not in ['trace','initial','root_forces_N','root_torques_Nm']}),flush=True)
